-- Harden staff workflow updates and move auth checks into private helper functions.
create or replace function private.qaaga_current_email() returns text language sql stable security definer set search_path=public,private,pg_temp as $$ select lower(coalesce(auth.jwt()->>'email','')); $$;
create or replace function private.qaaga_is_property_owner(p_property_id text) returns boolean language sql stable security definer set search_path=public,private,pg_temp as $$ select exists(select 1 from public.properties p where p.id=p_property_id and lower(p.host_email)=private.qaaga_current_email()); $$;
grant execute on function private.qaaga_current_email() to authenticated;grant execute on function private.qaaga_is_property_owner(text) to authenticated;
drop policy if exists qaaga_property_staff_read on public.property_staff_assignments;create policy qaaga_property_staff_read on public.property_staff_assignments for select to authenticated using((select auth.uid())=user_id or (select private.qaaga_is_super_admin()) or (select private.qaaga_is_property_owner(property_id)));
drop policy if exists qaaga_property_staff_manage on public.property_staff_assignments;create policy qaaga_property_staff_manage on public.property_staff_assignments for all to authenticated using((select private.qaaga_is_super_admin()) or (select private.qaaga_is_property_owner(property_id))) with check((select private.qaaga_is_super_admin()) or (select private.qaaga_is_property_owner(property_id)));
drop policy if exists qaaga_support_ticket_create on public.support_tickets;create policy qaaga_support_ticket_create on public.support_tickets for insert to authenticated with check(requester_id=(select auth.uid()) and lower(requester_email)=(select private.qaaga_current_email()));
drop policy if exists qaaga_service_fee_ledger_finance_write on public.service_fee_ledger;
create policy qaaga_service_fee_ledger_finance_insert on public.service_fee_ledger for insert to authenticated with check((select private.qaaga_has_role('finance')) or (select private.qaaga_is_super_admin()));
create policy qaaga_service_fee_ledger_finance_update on public.service_fee_ledger for update to authenticated using((select private.qaaga_has_role('finance')) or (select private.qaaga_is_super_admin())) with check((select private.qaaga_has_role('finance')) or (select private.qaaga_is_super_admin()));
create or replace function private.qaaga_guard_identity_review() returns trigger language plpgsql security definer set search_path=public,private,pg_temp as $$ begin if private.qaaga_is_super_admin() then return new; end if; if not private.qaaga_has_role('verification') then raise exception 'Verification role required.'; end if; if (to_jsonb(new)-array['status','rejection_reason','reviewed_by','reviewed_at','updated_at'])<>(to_jsonb(old)-array['status','rejection_reason','reviewed_by','reviewed_at','updated_at']) then raise exception 'Verification staff may only record review decision and metadata.'; end if; return new; end; $$;
revoke all on function private.qaaga_guard_identity_review() from public,anon,authenticated;drop trigger if exists qaaga_guard_identity_review on public.identity_verifications;create trigger qaaga_guard_identity_review before update on public.identity_verifications for each row execute function private.qaaga_guard_identity_review();
create or replace function private.qaaga_guard_support_ticket_update() returns trigger language plpgsql security definer set search_path=public,private,pg_temp as $$ begin if private.qaaga_is_super_admin() then return new; end if; if not private.qaaga_has_role('support') then raise exception 'Customer Support role required.'; end if; if (to_jsonb(new)-array['status','priority','assigned_to','updated_at','resolved_at'])<>(to_jsonb(old)-array['status','priority','assigned_to','updated_at','resolved_at']) then raise exception 'Support staff may only update ticket workflow fields.'; end if; return new; end; $$;
revoke all on function private.qaaga_guard_support_ticket_update() from public,anon,authenticated;drop trigger if exists qaaga_guard_support_ticket_update on public.support_tickets;create trigger qaaga_guard_support_ticket_update before update on public.support_tickets for each row execute function private.qaaga_guard_support_ticket_update();
create or replace function private.qaaga_guard_service_fee_update() returns trigger language plpgsql security definer set search_path=public,private,pg_temp as $$ begin if private.qaaga_is_super_admin() then return new; end if; if not private.qaaga_has_role('finance') then raise exception 'Finance role required.'; end if; if (to_jsonb(new)-array['status','payment_method','external_reference','notes','paid_at','updated_at'])<>(to_jsonb(old)-array['status','payment_method','external_reference','notes','paid_at','updated_at']) then raise exception 'Finance staff may not alter booking, amount, currency, or entry type.'; end if; return new; end; $$;
revoke all on function private.qaaga_guard_service_fee_update() from public,anon,authenticated;drop trigger if exists qaaga_guard_service_fee_update on public.service_fee_ledger;create trigger qaaga_guard_service_fee_update before update on public.service_fee_ledger for each row execute function private.qaaga_guard_service_fee_update();
create or replace function private.qaaga_guard_property_manager_update() returns trigger language plpgsql security definer set search_path=public,private,pg_temp as $$ begin if private.qaaga_is_super_admin() or private.qaaga_is_property_owner(old.id) then return new; end if; if not private.qaaga_has_property_role(old.id,'property_manager') then raise exception 'Property Manager role required.'; end if; if (to_jsonb(new)-array['title','description','price_daily','two_night_price_usd','price_weekly','price_monthly','max_guests','bedrooms','bathrooms','beds','square_feet','image','gallery','amenities','facilities','updated_at'])<>(to_jsonb(old)-array['title','description','price_daily','two_night_price_usd','price_weekly','price_monthly','max_guests','bedrooms','bathrooms','beds','square_feet','image','gallery','amenities','facilities','updated_at']) then raise exception 'Property Managers may edit listing content but not ownership or approval.'; end if; return new; end; $$;
revoke all on function private.qaaga_guard_property_manager_update() from public,anon,authenticated;drop trigger if exists qaaga_guard_property_manager_update on public.properties;create trigger qaaga_guard_property_manager_update before update on public.properties for each row execute function private.qaaga_guard_property_manager_update();